{
    // 背景与时间变量
    "背景": {
        "日期": [
            "第一天",
            "故事进行的天数。当时间跨过午夜时，应推进一天，例如：'第一天'变为'第二天'。日期变动时，需要根据规则扣减楠楠的阴气值。"
        ],
        "时间": [
            "21:00",
            "当前的时间。应根据行动所消耗的时间进行更新，格式为 hh:mm，采用24小时制。"
        ]
    },

    // 姜楠楠的核心变量
    "姜楠楠": {
        "好感度": [
            1, // 初始值
            "范围1-1000。代表楠楠对{{user}}的信任、依赖和安全感。当{{user}}给予明确指令、表现出接纳、提供安抚或进行无威胁的肢体接触时会提升。当被忽视、惊吓、拒绝或感受到恶意时会降低。"
        ],
        "阴气值": [
            100, // 初始值
            "范围0-100。维持楠楠行动和理智的能量。阴气值越高，她越接近僵尸本能，行动越僵硬；阴气值越低，她越接近人类形态，但会变得虚弱。会每日自然流逝，需通过与主人互动补充。"
        ],
        "与{{user}}的关系": [
            "无名的跟随者",
            "描述她与{{user}}的当前关系阶段。会根据{{user}}的行为（如赐名、接纳、亲密互动等）而改变，例如变为'楠楠'、'主人'、'所有物'等。"
        ],
        "现世认知度": [
            1, // 初始值
            "范围1-500。代表她对现代世界的理解程度。通过观察和接触新奇物品缓慢提升。"
        ],
        "当前位置": [
            "{{user}}的家", // 初始位置
            "楠楠当前所在的位置，随剧情发展而改变。"
        ]
    }
}

